const root=path.resolve(fileURLToPath(new URL('../../workshop/dist/',import.meta.url))),results=fileURLToPath(new URL('./workshop-results/',import.meta.url));
await fs.mkdir(results,{recursive:true});
const base='/Netaniya/eliana-n25x/workshop/';
const mime={'.html':'text/html','.mjs':'text/javascript','.js':'text/javascript','.css':'text/css','.json':'application/json','.webmanifest':'application/manifest+json','.ttf':'font/ttf','.png':'image/png','.webp':'image/webp','.txt':'text/plain'};
const server=createServer(async(req,res)=>{try{let name=decodeURIComponent(new URL(req.url,'http://localhost').pathname);if(!name.startsWith(base))throw Error();name=name.slice(base.length)||'index.html';const file=path.resolve(root,name);if(!file.startsWith(root+path.sep))throw Error();const bytes=await fs.readFile(file);res.writeHead(200,{'Content-Type':mime[path.extname(file)]||'application/octet-stream','Cache-Control':'no-store'});res.end(bytes);}catch{res.writeHead(404);res.end('not found');}});
await new Promise(resolve=>server.listen(4181,'127.0.0.1',resolve));
const scope=process.env.ELIANA_BROWSER_SCOPE||'desktop',url='http://127.0.0.1:4181'+base+'?qa=1';
const metadata=JSON.parse(await fs.readFile(path.join(root,'build-info.json'),'utf8'));
const report={scope,buildVersion:metadata.version,author:'Natalie Ragulina',startedAt:new Date().toISOString(),checks:[],errors:[],physicalDevicesTested:false};
const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-webgl','--ignore-gpu-blocklist','--enable-unsafe-swiftshader']});
const context=await browser.newContext(scope==='touch'?{viewport:{width:390,height:844},hasTouch:true,isMobile:true,deviceScaleFactor:1}:{viewport:{width:1360,height:960}});
// Seed only the app's top-level origin. Init scripts also run inside sandboxed
// project previews, where localStorage is intentionally unavailable.
await context.addInitScript(()=>{if(window!==window.top||!location.pathname.startsWith('/Netaniya/eliana-n25x/workshop/'))return;if(!localStorage.getItem('eliana-n25x.save.v1'))localStorage.setItem('eliana-n25x.save.v1','classic-sentinel');if(!localStorage.getItem('eliana-n25x.3d.v1'))localStorage.setItem('eliana-n25x.3d.v1','adventure-sentinel');});
const page=await context.newPage();page.setDefaultTimeout(30000);page.on('pageerror',e=>report.errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')report.errors.push(m.text());});
function check(name,detail={}){report.checks.push({name,...detail});console.log('PASS '+name,JSON.stringify(detail));}
const click=async selector=>{const el=page.locator(selector).first();if(!await el.isVisible()){const details=el.locator('xpath=ancestor::details').first();if(await details.count()){const summary=details.locator('summary').first();if(scope==='touch')await summary.tap();else await summary.click();}}await el.scrollIntoViewIfNeeded();if(scope==='touch')await el.tap();else await el.click();};
const state=()=>page.evaluate(key=>JSON.parse(localStorage.getItem(key)),SAVE_KEY);
const waitText=(selector,text)=>page.waitForFunction(([s,t])=>document.querySelector(s)?.textContent.includes(t),[selector,text]);
const ready=async()=>{await page.waitForFunction(()=>document.body.dataset.ready==='3d');await page.waitForFunction(()=>/phase [1-9]/.test(document.querySelector('#qa').textContent),null,{timeout:60000});await page.evaluate(()=>document.fonts.ready);};
async function settingsLanguage(lang){await click('#settings-button');await page.locator('#dialog [data-language]').selectOption(lang);await click('[data-do=close]');}
async function screenshot(name){await page.waitForTimeout(500);await page.locator('#qa').evaluate(el=>el.style.display='none');await page.screenshot({path:path.join(results,name+'.png'),fullPage:false});await page.locator('#qa').evaluate(el=>el.style.display='');}
async function download(selector,name){const pending=page.waitForEvent('download');await click(selector);const file=await pending;await file.saveAs(path.join(results,name));return fs.readFile(path.join(results,name));}
async function noOverflow(){assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),'no horizontal page overflow');}
async function readableLayoutCheck(){
 const widths=scope==='touch'?[320,844]:[760,1360],layouts=[];
 async function bounds(){await noOverflow();const bad=await page.locator('#content .buttons>button,#content .choice,#content .daily-card>button,#content .action-card,#content .subject-list button,#navigation button').evaluateAll(els=>els.filter(el=>el.getBoundingClientRect().width>0&&el.scrollWidth>el.clientWidth+1).map(el=>el.textContent.trim()));assert.deepEqual(bad,[],'readable button labels stay inside their controls');}
 for(const width of widths){await page.setViewportSize({width,height:width===844?390:960});
  for(const lang of ['de','en','ru','uk']){
   await page.locator('#site-language').selectOption(lang);await click('#navigation [data-do=home]');await bounds();
   assert(await page.locator('#content .help').first().evaluate(el=>parseFloat(getComputedStyle(el).fontSize)>=16));
   assert(await page.locator('.action-card small').first().evaluate(el=>parseFloat(getComputedStyle(el).fontSize)>=14));
   await click('#navigation [data-do=learn]');await bounds();await click('[data-subject=mathCourse]');await bounds();
   await click('#navigation [data-do=create]');await bounds();await click('[data-do=piano]');await bounds();
   await click('#settings-button');assert(await page.locator('#dialog .help').first().evaluate(el=>parseFloat(getComputedStyle(el).fontSize)>=16));await noOverflow();await click('[data-do=close]');layouts.push({width,lang});
  }
 }
 await page.setViewportSize(scope==='touch'?{width:390,height:844}:{width:1360,height:960});await page.locator('#site-language').selectOption('ru');await click('#navigation [data-do=home]');await screenshot(scope+'-readable-home');
 check('medium-size text and vivid controls remain readable without overflowing labels on narrow, landscape and desktop layouts in all four UI languages',{layouts,bodyTextAtLeast:16,cardDescriptionsAtLeast:14});
}
